// Returns { total (cents, before tax), applied: [codes that took effect] }.
export function applyCoupons(cart, codes) {
  let total = subtotal(cart)
  const applied = []
  for (const code of codes) {
    const coupon = COUPONS[code]
    if (!coupon) continue
    if (coupon.type === 'percent') total -= Math.round((total * coupon.value) / 100)
    else total -= coupon.value
    applied.push(code)
  }
  return { total, applied }
}

input.new_string:
// Returns { total (cents, before tax), applied: [codes that took effect] }.
// Rules: only the largest percentage coupon counts, computed off the subtotal
// before any fixed-amount coupons; fixed coupons combined can take off at most
// half the subtotal; a code entered more than once counts once; total floors at 0.
export function applyCoupons(cart, codes) {
  const sub = subtotal(cart)

  const seen = new Set()
  const validCodes = []
  for (const code of codes) {
    if (seen.has(code) || !COUPONS[code]) continue
    seen.add(code)
    validCodes.push(code)
  }

  let bestPercentCode = null
  for (const code of validCodes) {
    const coupon = COUPONS[code]
    if (coupon.type === 'percent' && (!bestPercentCode || coupon.value > COUPONS[bestPercentCode].value)) {
      bestPercentCode = code
    }
  }

  const percentDiscount = bestPercentCode ? Math.round((sub * COUPONS[bestPercentCode].value) / 100) : 0

  const fixedCodes = validCodes.filter((code) => COUPONS[code].type === 'fixed')
  const fixedSum = fixedCodes.reduce((sum, code) => sum + COUPONS[code].value, 0)
  const fixedDiscount = Math.min(fixedSum, Math.floor(sub / 2))

  const total = Math.max(0, sub - percentDiscount - fixedDiscount)
  const applied = validCodes.filter((code) => code === bestPercentCode || COUPONS[code].type === 'fixed')

  return { total, applied }
}

