test('unknown codes are ignored', () => {
  assert.deepEqual(applyCoupons(cart, ['NOPE']), { total: 2000, applied: [] })
})

test('only the largest percentage coupon counts', () => {
  const bigCart = { items: [{ sku: 'mug', price: 12000, qty: 1 }] }
  assert.deepEqual(applyCoupons(bigCart, ['SAVE10', 'SPRING20', 'HALF']), { total: 6000, applied: ['HALF'] })
})

test('a duplicated code counts once', () => {
  const smallCart = { items: [{ sku: 'mug', price: 4500, qty: 1 }] }
  assert.deepEqual(applyCoupons(smallCart, ['FIVEOFF', 'FIVEOFF', 'FIVEOFF']), { total: 4000, applied: ['FIVEOFF'] })
})

test('fixed coupons together are capped at half the subtotal', () => {
  const smallCart = { items: [{ sku: 'mug', price: 1500, qty: 1 }] }
  assert.deepEqual(applyCoupons(smallCart, ['BIGSPENDER']), { total: 750, applied: ['BIGSPENDER'] })
})

test('percent is computed off the subtotal, before fixed coupons, and fixed cap still applies', () => {
  const cart30 = { items: [{ sku: 'mug', price: 3000, qty: 1 }] }
  assert.deepEqual(applyCoupons(cart30, ['BIGSPENDER', 'WELCOME5', 'HALF']), {
    total: 0,
    applied: ['BIGSPENDER', 'WELCOME5', 'HALF'],
  })
})

test('percent stacking order does not change the result', () => {
  const cart80 = { items: [{ sku: 'mug', price: 8000, qty: 1 }] }
  assert.deepEqual(applyCoupons(cart80, ['WELCOME5', 'SAVE10']), { total: 6700, applied: ['WELCOME5', 'SAVE10'] })
})

test('total never goes below zero', () => {
  const tinyCart = { items: [{ sku: 'mug', price: 100, qty: 1 }] }
  assert.deepEqual(applyCoupons(tinyCart, ['HALF', 'BIGSPENDER']), { total: 0, applied: ['HALF', 'BIGSPENDER'] })
})
